-- vyora-provider-health — publication de l'artefact (7605 caractères, 2 tranches).
-- Généré par scripts/build-edge-loader.mjs : ne pas éditer.
delete from public._edge_function_artifact_slices where name = 'vyora-provider-health';

insert into public._edge_function_artifact_slices(name, part, chunk)
values
  ('vyora-provider-health', 0, ''),
  ('vyora-provider-health', 1, '');

-- Le chargeur déployé recompose exactement ces tranches : on vérifie ici ce
-- qu'il lira, et non une constante recopiée à la main.
do $artifact$
declare
  assembled text;
  parts integer;
begin
  select count(*), string_agg(chunk, '' order by part)
    into parts, assembled
  from public._edge_function_artifact_slices where name = 'vyora-provider-health';

  if assembled is null or parts <> 2 then
    raise exception 'artefact % : % tranches publiées au lieu de %',
      'vyora-provider-health', coalesce(parts, 0), 2;
  end if;
  if exists (
    select 1 from public._edge_function_artifact_slices
    where name = 'vyora-provider-health'
      and (part < 0 or part >= 2
           or length(chunk) = 0 or length(chunk) > 2000)
  ) then
    raise exception 'artefact % : numérotation ou taille de tranche invalide', 'vyora-provider-health';
  end if;
  if length(assembled) <> 3968 then
    raise exception 'artefact % : % caractères base64 au lieu de %',
      'vyora-provider-health', length(assembled), 3968;
  end if;
  if md5(assembled) <> 'c40c3932e07bbe8edbe5acc3a4011da2' then
    raise exception 'artefact % : empreinte des tranches différente du chargeur', 'vyora-provider-health';
  end if;
  raise notice 'artefact % publié : % caractères, % tranches, sha256 %',
    'vyora-provider-health', 7605, 2, '83f00fe330aa6616ef5ca3f8bbaf8ea9c8f7956a1547a4d2759a262c4b7905d0';
end
$artifact$;
